def eval_expression(expr: str) -> int:
    """
    四則演算式を計算する関数。
    - 演算の優先順位（括弧 > 掛け算/割り算 > 加算/減算）を考慮
    - 負の数をサポート
    - ゼロで割る場合は ZeroDivisionError を引き起こす

    Args:
        expr (str): 計算したい数式。例: "3 + 4 * (2 - 1)"

    Returns:
        int: 計算結果
    """
    # 余分な空白を除去
    expr = expr.strip()
    if not expr:
        raise ValueError("empty expression")

    pos = [0]  # 現在の位置を保持するための可変オブジェクト

    def parse_expression():
        """加算・減算の処理"""
        left = parse_term()
        while pos[0] < len(expr):
            ch = expr[pos[0]]
            if ch == '+':
                pos[0] += 1
                right = parse_term()
                left = left + right
            elif ch == '-':
                pos[0] += 1
                right = parse_term()
                left = left - right
            else:
                break
        return left

    def parse_term():
        """乗算・除算の処理"""
        left = parse_factor()
        while pos[0] < len(expr):
            ch = expr[pos[0]]
            if ch == '*':
                pos[0] += 1
                right = parse_factor()
                left = left * right
            elif ch == '/':
                pos[0] += 1
                right = parse_factor()
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                left = left // right  # 整数割り算
            else:
                break
        return left

    def parse_factor():
        """単項演算子、括弧、数の処理"""
        if pos[0] >= len(expr):
            raise ValueError("unexpected end of expression")

        ch = expr[pos[0]]

        # 単項演算子（+/-）の処理
        if ch == '+':
            pos[0] += 1
            return parse_factor()
        elif ch == '-':
            pos[0] += 1
            return -parse_factor()

        # 括弧の処理
        if ch == '(':
            pos[0] += 1  # '(' をスキップ
            result = parse_expression()
            if pos[0] >= len(expr) or expr[pos[0]] != ')':
                raise ValueError("missing closing parenthesis")
            pos[0] += 1  # ')' をスキップ
            return result

        # 数の処理
        if ch.isdigit():
            start = pos[0]
            while pos[0] < len(expr) and expr[pos[0]].isdigit():
                pos[0] += 1
            return int(expr[start:pos[0]])

        raise ValueError(f"unexpected character at position {pos[0]}: {ch}")

    result = parse_expression()

    # 完全に読み取れたか確認
    if pos[0] != len(expr):
        raise ValueError(f"incomplete expression at position {pos[0]}: '{expr[pos[0]]}'")

    return result
